const fade = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

function gd(
  ix: number, iy: number, iz: number,
  dx: number, dy: number, dz: number
) {
  const h = PERM[(PERM[(PERM[ix & 255] + (iy & 255)) & 255] + (iz & 255)) & 255] * 3;
  return GR[h] * dx + GR[h + 1] * dy + GR[h + 2] * dz;
}

function pn(x: number, y: number, z: number) {
  const X = Math.floor(x), Y = Math.floor(y), Z = Math.floor(z);
  const xf = x - X, yf = y - Y, zf = z - Z;
  const u = fade(xf), v = fade(yf), w = fade(zf);

  return 1.6 * lerp(
    lerp(
      lerp(gd(X, Y, Z, xf, yf, zf), gd(X + 1, Y, Z, xf - 1, yf, zf), u),
      lerp(gd(X, Y + 1, Z, xf, yf - 1, zf), gd(X + 1, Y + 1, Z, xf - 1, yf - 1, zf), u),
      v
    ),
    lerp(
      lerp(gd(X, Y, Z + 1, xf, yf, zf - 1), gd(X + 1, Y, Z + 1, xf - 1, yf, zf - 1), u),
      lerp(gd(X, Y + 1, Z + 1, xf, yf - 1, zf - 1), gd(X + 1, Y + 1, Z + 1, xf - 1, yf - 1, zf - 1), u),
      v
    ),
    w
  );
}

/* Radio de la figura en cada dirección: pliegues grandes y fluidos */
function radio(dx: number, dy: number, dz: number) {
  const f = 1.45, warp = 0.7, amp = 0.26, pw = 1.8, w2 = 0.12, lobe = 0.07, base = 1.22;

  const x = dx + pn(dx + 4, dy, dz) * warp;
  const y = dy + pn(dx, dy + 4, dz) * warp;
  const z = dz + pn(dx, dy, dz + 4) * warp;

  const r1 = Math.pow(Math.max(0, 1 - Math.abs(pn(x * f, y * f, z * f))), pw);
  const r2 = Math.pow(Math.max(0, 1 - Math.abs(pn(x * f * 2.3 + 5, y * f * 2.3, z * f * 2.3))), pw);
  const lob = pn(dx * 0.9 + 2, dy * 0.9, dz * 0.9) * lobe;

  return base + (r1 + (r2 * w2) / amp * 0.5 - 0.55) * amp + lob;
}

let geometriaGuardada: THREE.BufferGeometry | null = null;

export function obtenerGeometria(): THREE.BufferGeometry {
  if (geometriaGuardada) return geometriaGuardada;

  const geo = new THREE.IcosahedronGeometry(1, 32);
  const pos0 = geo.attributes.position as THREE.BufferAttribute;
  const N = pos0.count;

  const P = new Float32Array(N * 3);
  const Nn = new Float32Array(N * 3);
  const e = 0.004;

  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  const n = new THREE.Vector3();
  const t1 = new THREE.Vector3();
  const t2 = new THREE.Vector3();
  const d = new THREE.Vector3();
  const v = new THREE.Vector3();

  const punto = (vec: THREE.Vector3, salida: THREE.Vector3) => {
    const l = Math.hypot(vec.x, vec.y, vec.z);
    const dx = vec.x / l, dy = vec.y / l, dz = vec.z / l;
    const r = radio(dx, dy, dz);
    return salida.set(dx * r, dy * r, dz * r);
  };

  for (let i = 0; i < N; i++) {
    d.set(pos0.getX(i), pos0.getY(i), pos0.getZ(i)).normalize();
    punto(d, a);

    t1.crossVectors(d, Math.abs(d.y) > 0.99 ? v.set(1, 0, 0) : v.set(0, 1, 0)).normalize();
    t2.crossVectors(d, t1).normalize();

    punto(v.copy(d).addScaledVector(t1, e), b);
    punto(v.copy(d).addScaledVector(t2, e), c);

    n.crossVectors(b.sub(a), c.sub(a)).normalize();
    if (n.dot(d) < 0) n.negate();

    P[i * 3] = a.x; P[i * 3 + 1] = a.y; P[i * 3 + 2] = a.z;
    Nn[i * 3] = n.x; Nn[i * 3 + 1] = n.y; Nn[i * 3 + 2] = n.z;
  }

  geo.setAttribute("position", new THREE.BufferAttribute(P, 3));
  geo.setAttribute("normal", new THREE.BufferAttribute(Nn, 3));

  geometriaGuardada = geo;
  return geo;
}
